function saveDemo(){syncParticipationIndex();try{sessionStorage.setItem('linkage-demo-v2',JSON.stringify({cases,caseRecords,caseTracks,caseGenders,participations,pendingTasks,followups,caseBasics,basicSuggestions,basicHistory}))}catch(e){}}
try{const saved=JSON.parse(sessionStorage.getItem('linkage-demo-v2')||'null');if(saved?.cases&&saved?.caseRecords){cases=saved.cases;caseBasics=saved.caseBasics||caseBasics;basicSuggestions=saved.basicSuggestions||{};basicHistory=saved.basicHistory||{};caseRecords=saved.caseRecords;caseTracks=saved.caseTracks||{};caseGenders=saved.caseGenders||caseGenders;participations.splice(0,participations.length,...saved.participations);pendingTasks.splice(0,pendingTasks.length,...saved.pendingTasks);if(saved.followups)followups.splice(0,followups.length,...saved.followups);records=caseRecords[0]||[]}}catch(e){}


const taskOptions=['安排初次訪視','安排電話關懷','協助安排就醫／回診','確認活動參與意願','確認交通／接送安排','安排首次活動陪同','追蹤活動參與回饋','確認居家支持需求'];
function caseSummary(){return `<section class="card" style="margin-bottom:20px"><div class="row between"><h2>服務摘要</h2>${btn('編輯',"modal='editSummary';render()",'secondary')}</div><dl class="details"><dt>最後接觸</dt><dd>${esc(cases[selectedCase][2]||'尚未接觸')}</dd><dt>距今天數</dt><dd>${cases[selectedCase][3]===null?'—':cases[selectedCase][3]+' 天'}</dd><dt>待確認事項</dt><dd>${esc(cases[selectedCase][4])}</dd></dl></section>`}
function editSummaryForm(){const task=cases[selectedCase][4],other=!taskOptions.includes(task);return `<h2>編輯${esc(cname())}的服務摘要</h2><form onsubmit="saveCaseSummary(event)"><label class="field">最後接觸日期<input id="editContactDate" type="date" max="2026-10-05" value="${cases[selectedCase][2].replaceAll('/','-')}" onchange="syncContactDays()"></label><label class="field">距今天數<input id="editContactDays" type="number" min="0" step="1" value="${cases[selectedCase][3]??''}" placeholder="尚未接觸" oninput="syncContactDate()"></label><p class="small space">日期與天數連動，依 Demo 今日 2026/10/05 計算；留空表示尚未接觸。</p><label class="field">待確認事項<select id="caseTask" onchange="toggleOtherTask(this.value)">${[...taskOptions,'其他'].map(t=>`<option ${t===(other?'其他':task)?'selected':''}>${t}</option>`).join('')}</select></label><label class="field" id="otherTaskField" ${other?'':'hidden'}>其他待確認事項<input id="caseTaskOther" value="${other?esc(task):''}" ${other?'required':'disabled'} placeholder="請描述需要處理的事項" maxlength="160"></label><div class="row between gap">${btn('取消',"modal='';render()",'secondary')}<button class="btn" type="submit">儲存修改</button></div></form>`}
function saveCaseSummary(event){event.preventDefault();const task=$('#caseTask').value==='其他'?$('#caseTaskOther').value.trim():$('#caseTask').value;if(!task){$('#caseTaskOther').setCustomValidity('請填寫待確認事項');$('#caseTaskOther').reportValidity();$('#caseTaskOther').oninput=function(){this.setCustomValidity('')};return}const date=$('#editContactDate').value;cases[selectedCase][2]=date.replaceAll('-','/');cases[selectedCase][3]=date?contactDays(date):null;let pending=pendingTasks.find(t=>t.caseId===selectedCase);if(pending){pending.task=task;pending.note='依服務摘要更新，請於下次接觸確認。'}else pendingTasks.push({caseId:selectedCase,task,note:'請於下次接觸確認。'});for(const followup of followups)if(followup.caseId===selectedCase)followup.task=task;cases[selectedCase][4]=task;modal='';saveDemo();render();toast('已更新'+cname()+'的服務摘要')}


function contactDays(date){return Math.max(0,Math.round((Date.UTC(2026,9,5)-Date.parse(date+'T00:00:00Z'))/86400000))}
function syncContactDays(){const date=$('#editContactDate').value;$('#editContactDays').value=date?contactDays(date):''}
function syncContactDate(){const raw=$('#editContactDays').value;if(raw===''){$('#editContactDate').value='';return}const days=Number(raw);if(!Number.isInteger(days)||days<0)return;$('#editContactDate').value=new Date(Date.UTC(2026,9,5)-days*86400000).toISOString().slice(0,10)}
function editCaseFromList(id){selectedCase=id;records=caseRecords[id]||(caseRecords[id]=[]);modal='editSummary';render()}

function render(){syncParticipationIndex();$('#app').innerHTML=logged?shell(({home,statDetail,cases:caseList,case:casePage,result,newRecord,resources:resourcePage,feedback,feedbackDetail,success,analytics,settings}[route]||home)()):login();if(modal){requestAnimationFrame(()=>$('.modal button, .modal input')?.focus())}}
