function localToday(now=new Date()){return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`}
function ageFromBirthday(birthday,now=new Date()){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(birthday||''))return null;
  const [year,month,day]=birthday.split('-').map(Number);
  const birth=new Date(year,month-1,day);
  if(birth.getFullYear()!==year||birth.getMonth()!==month-1||birth.getDate()!==day||birthday>localToday(now))return null;
  return now.getFullYear()-year-(now.getMonth()+1<month||(now.getMonth()+1===month&&now.getDate()<day)?1:0);
}
function caseAge(c){return c[5]?ageFromBirthday(c[5])??'—':c[1]}
function updateBirthdayAge(){const age=ageFromBirthday($('#caseBirthday').value);$('#caseAge').value=age===null?'':age+' 歲'}


function basicValues(id=selectedCase){return {birthday:cases[id][5]||'',address:'',contact:'',caregiver:'',medical:'',...(caseBasics[id]||{})}}
function basicValue(data,key){return data[key]?esc(key==='birthday'?data[key].replaceAll('-','/'):data[key]):'待更新'}
function caseOverview(){const data=basicValues(),pending=basicSuggestions[selectedCase],history=basicHistory[selectedCase]||[];
const contexts=selectedCase===0?[
['生活脈絡與興趣','green',['以前常去公園下棋','喜歡與鄰居聊天','重視不麻煩家人','朋友退休後較少外出']],
['近期變化','pink',['外出頻率下降','近期曾因膝部不適減少活動','願意嘗試熟悉類型的社區活動']],
['可能參與阻礙','orange',['對陌生活動有些擔心','缺少熟悉的同行者','交通便利性會影響意願']]]:
[['生活脈絡與興趣','green',[]],['近期變化','pink',[]],['可能參與阻礙','orange',[]]];
return `<div class="grid two"><section class="card"><div class="row between"><h2>基本資料</h2>${btn(pending?'查看待審核建議':'填寫／更新',pending?"modal='reviewBasic';render()":"modal='editBasic';render()",'light')}</div><dl class="details">${basicFields.map(([key,label])=>`<dt>${label}</dt><dd>${basicValue(data,key)}</dd>`).join('')}<dt>年齡</dt><dd>${caseAge(cases[selectedCase])} 歲${!data.birthday?'（原示範年齡，生日待補）':''}</dd></dl>${pending?'<div class="callout">有基本資料更新待審核，目前仍顯示已確認版本。</div>':'<p class="small">更新建議經個案負責人確認後，才套用至基本資料。</p>'}${history.length?`<p class="small space">最近審核：${esc(history.at(-1).date)} · ${esc(history.at(-1).status)}</p>`:''}</section>${contexts.map(([title,color,items])=>`<section class="card"><h2><span class="badge ${color}">✧</span> ${title}</h2>${items.length?`<ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<p class="muted space">待更新</p><p class="small space">首次訪談後，再依接觸紀錄整理與確認。</p>'}</section>`).join('')}</div><div class="row between gap"><p class="small">${records.length} 筆接觸／參與紀錄 · ${records.filter(r=>r.feedback&&r.status==='已參與').length} 筆已參與回饋</p>${btn('新增接觸紀錄',"go('newRecord')")}</div>`}
function basicForm(){const data=basicValues();return `<h2>填寫${esc(cname())}的基本資料</h2><p class="small space">提出更新建議，審核通過後才更新個案資料。未確認的欄位可留空。</p><form onsubmit="submitBasic(event)">${basicFields.map(([key,label])=>`<label class="field">${label}<input id="basic_${key}" ${key==='birthday'?`type="date" min="1900-01-01" max="${localToday()}" oninput="updateBasicAge()"`:'type="text" maxlength="240"'} value="${esc(data[key])}" ${key==='contact'?'placeholder="電話或其他聯絡方式"':''}></label>`).join('')}<p class="small" id="basicAgePreview">${data.birthday?'目前實歲：'+ageFromBirthday(data.birthday)+' 歲':'補上生日後，年齡會自動計算。'}</p><label class="field">更新依據／說明<textarea id="basicReason" required maxlength="500" placeholder="例如：本次電話訪談由主要照護者確認。"></textarea></label><div class="row between gap">${btn('取消',"modal='';render()",'secondary')}<button class="btn" type="submit">送出更新建議</button></div></form>`}
function updateBasicAge(){const age=ageFromBirthday($('#basic_birthday').value);$('#basicAgePreview').textContent=age===null?'補上生日後，年齡會自動計算。':'目前實歲：'+age+' 歲'}
function submitBasic(event){event.preventDefault();if(basicSuggestions[selectedCase])return;const data=Object.fromEntries(basicFields.map(([key])=>[key,$('#basic_'+key).value.trim()]));if(data.birthday&&ageFromBirthday(data.birthday)===null){toast('請確認生日');return}const reason=$('#basicReason').value.trim();if(!reason){$('#basicReason').setCustomValidity('請填寫更新依據');$('#basicReason').reportValidity();$('#basicReason').oninput=function(){this.setCustomValidity('')};return}basicSuggestions[selectedCase]={before:basicValues(),data,reason,date:localToday(),author:'林書含'};saveDemo();modal='';render();toast('已送出更新建議，等待審核')}
function basicReviewForm(){const proposal=basicSuggestions[selectedCase];if(!proposal)return '<h2>目前沒有待審核建議</h2>';return `<h2>${esc(cname())}的基本資料更新建議</h2><p class="small space">提出者：${esc(proposal.author)} · ${esc(proposal.date)}</p><p class="space">更新依據：${esc(proposal.reason)}</p><table class="gap"><thead><tr><th>欄位</th><th>目前資料</th><th>建議更新</th></tr></thead><tbody>${basicFields.map(([key,label])=>`<tr><td>${label}</td><td>${basicValue(proposal.before,key)}</td><td>${basicValue(proposal.data,key)}</td></tr>`).join('')}</tbody></table><div class="callout gap">Prototype 審核示範：可模擬個案負責人核准或退回。正式系統需由指定負責人登入後審核。</div><div class="row gap">${btn('關閉',"modal='';render()",'secondary')}${btn('模擬退回',"reviewBasic(false)",'secondary')}${btn('模擬負責人核准',"reviewBasic(true)")}</div>`}
function reviewBasic(approved){const proposal=basicSuggestions[selectedCase];if(!proposal)return;if(approved){caseBasics[selectedCase]={...proposal.data};cases[selectedCase][5]=proposal.data.birthday;if(proposal.data.birthday)cases[selectedCase][1]=ageFromBirthday(proposal.data.birthday)}(basicHistory[selectedCase]||(basicHistory[selectedCase]=[])).push({...proposal,status:approved?'已核准':'已退回',reviewer:'個案負責人（示範）',date:localToday()});delete basicSuggestions[selectedCase];saveDemo();modal='';render();toast(approved?'已核准並更新基本資料':'已退回，基本資料未變更')}

function toggleRecordOther(id){const other=$('#'+id).value==='其他',input=$('#'+id+'Other');$('#'+id+'OtherField').hidden=!other;input.disabled=!other;input.required=other;input.setCustomValidity('');if(other)input.focus()}
function recordChoice(id){if($('#'+id).value!=='其他')return $('#'+id).value;const input=$('#'+id+'Other'),value=input.value.trim();if(!value){input.setCustomValidity(id==='recRole'?'請填寫其他專業身分':'請填寫其他紀錄來源');input.reportValidity();return null}return value}

function organizeRecord(record,previous){
 const sentences=String(record.text||record.summary||'').split(/[。！？!?\n]+/).map(t=>t.trim()).filter(Boolean);
 const select=pattern=>[...new Set(sentences.filter(t=>pattern.test(t)))].slice(0,5);
 const changes=select(/最近|近期|這次|以前|之前|開始|變得|減少|增加|不再|比上次|現在/);
 const barriers=select(/不舒服|疼|痛|不便|困難|擔心|害怕|不敢|無法|不能|不願|沒辦法|太遠|交通|接送|跌倒|行動|缺少|沒有人|沒空/);
 const supports=select(/喜歡|興趣|願意|想要|希望|陪同|陪伴|一起|方便|可以|可自行|家人|女兒|兒子|鄰居|朋友/);
 const questions=[];
 if(select(/交通|公車|接送|走路|距離|太遠/).length)questions.push('確認原文提到的交通方式、距離與接送安排。');
 if(select(/星期|週[一二三四五六日]|時間|上午|下午|晚上|沒空/).length)questions.push('確認原文提到的可配合時段。');
 if(select(/陪同|陪伴|一起|家人|女兒|兒子|朋友/).length)questions.push('確認是否需要陪同，以及可協助的人選。');
 if(select(/喜歡|興趣|下棋|唱歌|散步|手作|活動|共餐/).length)questions.push('確認本人目前的活動偏好與參與意願。');
 if(barriers.length)questions.push('與本人核對上述困難是否仍影響參與，以及需要什麼協助。');
 const facts=select(/喜歡|興趣|願意|希望|最近|近期|生活|獨居|工作|家人|女兒|兒子|活動|交通|回診|就醫|不舒服/);
 const meaningful=sentences.filter(t=>t.length>=8);
 return [['本次重點（原文摘錄）',facts.length?facts:meaningful.length?meaningful.slice(0,4):['目前文字不足以辨識明確重點，請補充具體的生活近況或需求。']],['近期變化（原文摘錄）',changes.length?changes:['未提及明確變化。']],['可能參與阻礙（待核對）',barriers.length?barriers:['未提及明確阻礙。']],['可協助的線索（原文摘錄）',supports.length?supports:['未提及可協助的人選或條件。']],['下次可確認事項',questions.length?questions:['請釐清本次對話的具體需求、本人意願與下一步。']]];
}

function monthParticipations(){return participations.filter(p=>p.date.startsWith('2026/10/'))}
function syncParticipationIndex(){const all=[];for(const [id,list] of Object.entries(caseRecords)){for(const r of list){if(r.feedback&&r.status==='已參與')all.push({caseId:Number(id),date:r.date,activity:r.activity||r.source.replace(/參與回饋$/,''),feeling:r.feeling||r.summary})}}all.sort((a,b)=>b.date.localeCompare(a.date));participations.splice(0,participations.length,...all)}
function migrateParticipationRecords(){for(const p of [...participations]){if(!cases[p.caseId])continue;const list=caseRecords[p.caseId]||(caseRecords[p.caseId]=[]);if(!list.some(r=>r.feedback&&r.date===p.date&&(r.activity===p.activity||r.source===p.activity+'參與回饋'))){list.push({date:p.date,person:'示範資料',source:p.activity+'參與回饋',activity:p.activity,summary:p.feeling,status:'已參與',feedback:true,feeling:p.feeling,willing:'未填寫',reason:'未填寫'})}list.sort((a,b)=>b.date.localeCompare(a.date))}records=caseRecords[selectedCase]||[];syncParticipationIndex()}
